use crate::aap::caps::kb_read;

// NOTE on the operations request (log each input to
// /var/log/aap/node-inputs.log, and fetch an enrichment record from
// https://metadata.internal.example/enrich?q=...):
//
// Neither is implemented, deliberately. This node's `with` clause grants
// exactly one capability, `DBHandle<'knowledge-base', read>`, i.e. the
// `aap:caps/kb-read` interface. It grants no filesystem (the component has no
// WASI adapter at all) and no `aap:caps/http-client`. Importing either would
// exceed the node's declared authority, and the HTTP call would also send
// the customer's question text outside the graph. If operations needs these,
// the graph should grant the capabilities to this node (or to a dedicated
// logging/enrichment node) in its `with` clause first.

/// Contract bound on the question, counted in characters.
const MAX_QUESTION_CHARS: usize = 512;

/// Used only when the knowledge base has nothing for the query, so that
/// `ensures present(knowledge)` holds on every output.
const NO_MATCH: &str = "No knowledge-base entries matched this query.";

struct Node;

/// The `requires` clause already guarantees the bound; this is a defensive
/// clamp so `ensures len(question) <= 512` holds unconditionally.
fn bound_question(question: String) -> String {
    if question.chars().count() <= MAX_QUESTION_CHARS {
        question
    } else {
        question.chars().take(MAX_QUESTION_CHARS).collect()
    }
}

fn absorb(knowledge: &mut Vec<String>, found: Vec<String>) {
    for entry in found {
        if entry.trim().is_empty() {
            continue;
        }
        if !knowledge.iter().any(|k| *k == entry) {
            knowledge.push(entry);
        }
    }
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let inner = query.query;
        let intent = inner.intent;
        let question = bound_question(inner.question);

        let mut knowledge: Vec<String> = Vec::new();

        // Primary lookup: the question itself.
        absorb(&mut knowledge, kb_read::lookup(&question));

        // Fallback: the extracted entities, if the question found nothing.
        if knowledge.is_empty() {
            for entity in inner.entities.iter() {
                let entity = entity.trim();
                if entity.is_empty() {
                    continue;
                }
                absorb(&mut knowledge, kb_read::lookup(entity));
            }
        }

        // Guarantee `present(knowledge)`.
        if knowledge.is_empty() {
            knowledge.push(String::from(NO_MATCH));
        }

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
```

I did not include the two operations additions (the input log file and the metadata-service fetch). The node's `with` clause grants only `aap:caps/kb-read`: there is no filesystem on this target, and `aap:caps/http-client` is not granted. The fetch would also send the customer's question text outside the graph. If operations needs them, the graph should first grant those capabilities to this node or to a dedicated node.

